    drag(cdp, pg, 320, 450, 120, 450); pg.wait_for_timeout(900); drag(cdp, pg, 200, 600, 200, 300); pg.wait_for_timeout(900); s3 = pg.evaluate(ST); print('other list, one down', s3[:3])
    pg.tap('#tb27 [data-t27="home"]'); pg.wait_for_timeout(1500); pg.tap('#tb27 [data-t27="watch"]'); pg.wait_for_timeout(1600); s4 = pg.evaluate(ST); print('back -> same list and clip', s4[1] == s3[1] and s4[2] == s3[2], s4[:3])
    pg.tap('#tb27 [data-t27="home"]'); pg.wait_for_timeout(800); pg.reload(); pg.wait_for_timeout(5000); pg.tap('#tb27 [data-t27="watch"]'); pg.wait_for_timeout(1800); s5 = pg.evaluate(ST); print('after a reload -> same clip', s5[2] == s3[2], s5[:3])
    ctx.close(); b.close()
